			string moveSetsSaveFolder = SettingsHelper.GetMoveSetsSaveFolder();
			Directory.CreateDirectory(moveSetsSaveFolder);
			source = MoveSetHelpers.GetDefaultMoveSets(false);
			foreach (string path in Directory.GetFiles(moveSetsSaveFolder, "*.json", SearchOption.TopDirectoryOnly))
			{
				list.Add(new MoveSet
				{
					name = Path.GetFileName(path).Replace(".json", ""),
					fileName = Path.GetFileName(path)
				});
			}
			list = (from x in list
			orderby x.name
			select x).ToList<MoveSet>();
			list.AddRange(from x in source
			orderby x.communityMoveset, x.name
			select x);
			MoveSetHelpers.loadedMoveSetList = list;
			return list;
		}

		// Token: 0x0600127B RID: 4731 RVA: 0x000605FC File Offset: 0x0005E7FC
		public static List<MoveSet> FilterMovesets(List<MoveSet> movesets, bool playerIsAi = false)
		{
			if (IGameSettingsManager.singleton != null)
			{
				if (IGameSettingsManager.singleton.AllowedMovesetTypes == AllowedMovesetTypes.Community)
				{
					movesets = (from x in movesets
					where x.defaultMoveset
					select x).ToList<MoveSet>();
				}
				else if (IGameSettingsManager.singleton.AllowedMovesetTypes == AllowedMovesetTypes.Basic)
				{
					movesets = (from x in movesets
					where x.defaultMoveset && !x.communityMoveset
					select x).ToList<MoveSet>();
				}
			}
			if (playerIsAi)
			{
				movesets = (from x in movesets
				where !x.notUsableByAI
				select x).ToList<MoveSet>();
			}
			return movesets;
		}

