		// Token: 0x0600127E RID: 4734 RVA: 0x0006081C File Offset: 0x0005EA1C
		public static List<EquippedEquipment> VerifyEquippedEquipmentList(List<EquippedEquipment> equippedEquipmentList)
		{
			List<EquippedEquipment> list = new List<EquippedEquipment>();
			using (List<EquippedEquipment>.Enumerator enumerator = equippedEquipmentList.GetEnumerator())
			{
				while (enumerator.MoveNext())
				{
					EquippedEquipment equippedEquipment = enumerator.Current;
					if (equippedEquipment.equipment != null && equippedEquipment.equipment.equipmentPositions.Contains(equippedEquipment.position) && (from x in list
					where x.position == equippedEquipment.position
					select x).FirstOrDefault<EquippedEquipment>() == null)
					{
						list.Add(equippedEquipment);
					}
				}
			}
			return list;
		}

