		// Token: 0x06001280 RID: 4736 RVA: 0x0006094C File Offset: 0x0005EB4C
		public static MoveSet LocalizeDefaultMoveset(MoveSet moveset, bool localizeAll = false)
		{
			if (!SettingsHelper.disableMovesetLocalization)
			{
				moveset.unlocalizedName = moveset.name;
				moveset.name = LocalizationHelpers.LocalizedTextWithCheck(moveset.name, Array.Empty<object>());
				if (localizeAll)
				{
					foreach (Stance stance in moveset.stanceList)
					{
						stance.unlocalizedName = stance.name;
						stance.name = LocalizationHelpers.LocalizedTextWithCheck(stance.name, Array.Empty<object>());
						foreach (Move move in stance.moveList)
						{
							move.unlocalizedName = move.name;
							move.name = LocalizationHelpers.LocalizedTextWithCheck(move.name, Array.Empty<object>());
						}
					}
				}
			}
			return moveset;
		}

