		// Token: 0x06001289 RID: 4745 RVA: 0x00060E0C File Offset: 0x0005F00C
		public static MoveSet ConvertMoveSetToClassic(MoveSet moveSetToConvert)
		{
			MoveSet moveSet = null;
			if (moveSetToConvert != null)
			{
				moveSet = moveSetToConvert.GetClone();
				if (moveSet.stanceList != null)
				{
					List<Move> classicWalkMoves = MoveSetHelpers.GetClassicWalkMoves();
					for (int i = 0; i < moveSet.stanceList.Count; i++)
					{
						Stance stance = moveSet.stanceList[i];
						if (stance.moveList != null)
						{
							for (int j = stance.moveList.Count - 1; j > -1; j--)
							{
								Move move = stance.moveList[j];
								if (MoveSetHelpers.movementActionNames.Contains(move.playerInput))
								{
									stance.moveList.RemoveAt(j);
								}
								else if (move.jointMoveList != null)
								{
									MoveSetHelpers.ConvertMoveToClassic(move);
								}
							}
							for (int k = classicWalkMoves.Count - 1; k > -1; k--)
							{
								stance.moveList.Add(classicWalkMoves[k]);
							}
						}
					}
				}
			}
			return moveSet;
		}

		// Token: 0x0600128A RID: 4746 RVA: 0x00060EF8 File Offset: 0x0005F0F8
		public static Move ConvertMoveToClassic(Move move)
		{
			if (move != null && move.jointMoveList != null)
			{
				for (int i = move.jointMoveList.Count - 1; i > -1; i--)
				{
					JointMove jointMove = move.jointMoveList[i];
					if (MoveSetHelpers.lowerBodyJointTypes.Contains(jointMove.joint))
					{
						move.jointMoveList.RemoveAt(i);
					}
				}
				if (move.inputType == inputType.Passive)
				{
					List<JointMove> classicStanceJointMoves = MoveSetHelpers.GetClassicStanceJointMoves();
					for (int j = classicStanceJointMoves.Count - 1; j > -1; j--)
					{
						JointMove item = classicStanceJointMoves[j];
						move.jointMoveList.Add(item);
					}
				}
			}
			return move;
		}

